def enable_dsa_cp_with_o_proj_tp(
    attn_backend,
    kv_transfer_config,
    is_deepseek_v32,
):
    """Check if DSA-CP with o_proj TP should be enabled."""
    if not is_deepseek_v32:
        return False
    if kv_transfer_config is None:
        return False
    # 判断逻辑未明确体现 KV pooling 和 PD 混合模式的概念
    if attn_backend.use_sfa_cp:
        return True
    return False
